% The following is a function called lightfunc.m  It expects%  to recieve time in hours and the global variables.  It will%  return an estimated irradiance at the surface of the Earth %  for given hour on a given day.  Latitude and percent cloud %  cover can be varied from the master progam. The equations %  seems to break down towards the poles.% Programing by Daniel Roelke.% Formlulations and conversions from: %  Brock, T.D., 1981.  Ecological Modelling. 14:1-19.%---------------------------------------------------------------------------function Irrad = lightfunc2(t,I)time  = t/24;        % time is handed in as an hour and is converted to dayt     = floor(time);pi    = I.pi;Lat   = I.Lat_r;     mIo   = I.mIo;cloud = I.cloud;% Ka    = I.K_a;% depth = I.depth;%---------------------------------------------------------------------------% FIRST PART OF FUNCTION -- DAILY INTEGRATED IRRADIANCE% CALCULATIONS%  Vary solar constant with Earth's eccentrical orbitR1=1/((1+0.033*cos(2*pi*t/365)).^0.5); % Distance correction										%  for Earth's orbitIo=mIo/(R1^2);			% Time varying solar 										%  constant %  Calculate declination (north is positive)D1=23.45*sin(2*pi*(284+t)/365); % Declination (degrees)D1=D1*pi/180;		        % Declination (radians)%  Calculate day lengthW1=acos(-1*tan(Lat)*tan(D1));     % Hour-angle (radians)L1=2*W1/(15*pi/180);		% Day length (hours)sunrise=12-0.5*L1;		% Time of sunrise (hour)sunset=12+0.5*L1;		% Time of sunset  (hour)%  Calculate daily integrated light at the top of atmosphereterm1=W1*sin(Lat)*sin(D1);term2=sin(W1)*cos(Lat)*cos(D1);intIo=(24/pi)*Io*(term1+term2);	% Int. light top atmos.%  Calculate daily integrated light at the Earth's surfaceintIo=intIo*3/8;		% PAR at top of atmosphereintIo=intIo-0.7*cloud*intIo;    % Loss - cloud transmission%---------------------------------------------------------------------------% SECOND PART OF FUNCTION -- HOURLY IRRADIANCE FOR JD%  Use daily integrated irradiance to find hourly changes in %   irradiance throughout the day.  Assume changes are linear.  %   From sunrise to noon, I=a*t (where t=time of day minus %   sunrise, when t is less than 12 noon).  The slope is %   determined by setting the integration of a*t equal Io/2 for%   that day, where t=L1/2.% CALCULATIONS% Do time conversionn=24*(time-t);	% Time of day (hour)% Triangular function% Find linear equation for day and calculate Irrad %a=4*intIo/L1^2;		% Slope for the given day%if n<sunrise%  Irrad=0;		% Irradiance (quanta/cm2/s)%elseif n<12%  Irrad=a*(n-sunrise);%elseif n<sunset%  Irrad=a*((12-(n-12))-sunrise);%else%  Irrad=0;%end% Sine functionh=intIo*pi/(2*L1);%if n<sunrise%  Irrad=0;             % Irradiance (quanta/cm2/s)%elseif n<12%  Irrad=h*sin((n-sunrise)*pi/L1);%elseif n<sunset%  Irrad=h*sin(((12-(n-12))-sunrise)*pi/L1);%else%  Irrad=0;%end% Smoother sine if n<sunrise  Irrad=0;             % Irradiance (quanta/cm2/s)elseif n<sunset  Irrad=h/2*(1-sin((n-sunrise)*2*pi/L1+pi/2));else  Irrad=0;end% Return irradiance at given depth and turbidity% Irrad=Irrad*exp(-Ka*depth);returnend